// Audiobook player for the Listen page and the "Listen to this chapter" buttons on reading pages.
// Track list: window.TTH_TRACKS from tracks.js (generated by build_web.py): f = file, u = URL, t = title,
// d = length in seconds, p = reading page. Your place in each track is kept in this browser only.

(function () {
  "use strict";

  var T = window.TTH_TRACKS || [];
  if (!T.length) return;

  var KEY = "tth-audio";
  var SPEEDS = [1, 1.25, 1.5, 1.75, 2, 0.75];
  var state = { pos: {}, done: {}, last: null, speed: 1 };
  try {
    var saved = JSON.parse(localStorage.getItem(KEY));
    if (saved && typeof saved === "object") {
      state.pos = saved.pos || {};
      state.done = saved.done || {};
      state.last = typeof saved.last === "string" ? saved.last : null;
      state.speed = SPEEDS.indexOf(saved.speed) >= 0 ? saved.speed : 1;
    }
  } catch (e) {}
  function persist() { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch (e) {} }

  function indexOfFile(f) { for (var i = 0; i < T.length; i++) if (T[i].f === f) return i; return -1; }
  function clock(s) {
    s = Math.max(0, Math.floor(s || 0));
    var h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
    return (h ? h + ":" + (m < 10 ? "0" : "") : "") + m + ":" + (sec < 10 ? "0" : "") + sec;
  }
  function mins(s) {
    var m = Math.max(1, Math.round(s / 60));
    return m >= 60 ? Math.floor(m / 60) + " hr " + (m % 60) + " min" : m + " min";
  }
  // Where to start a track: the saved spot, unless it was finished or is within 5 s of the end.
  function startAt(i) {
    var p = state.pos[T[i].f] || 0;
    return p > 0 && p < T[i].d - 5 ? p : 0;
  }

  // ---------------------------------------------------------------- the player bar
  var ICON = {
    play: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg>',
    pause: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 5h4v14H7zM13 5h4v14h-4z"/></svg>',
    prev: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6h2v12H6zM9.5 12 18 18V6z"/></svg>',
    next: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M16 6h2v12h-2zM6 18l8.5-6L6 6z"/></svg>'
  };

  var audio = new Audio();
  audio.preload = "none";
  var cur = -1;          // index of the loaded track
  var queue = [];        // track indexes this player moves through
  var bar = null, ui = {};
  var seeking = false, lastSave = 0;

  function buildBar() {
    if (bar) return;
    bar = document.createElement("section");
    bar.className = "player";
    bar.setAttribute("aria-label", "Audiobook player");
    bar.innerHTML =
      '<div class="pl-in">' +
      '<div class="pl-info"><span class="pl-label">Now playing</span><strong class="pl-title"></strong></div>' +
      '<div class="pl-controls">' +
      '<button type="button" class="pl-prev" aria-label="Previous track">' + ICON.prev + "</button>" +
      '<button type="button" class="pl-back" aria-label="Back 15 seconds">−15</button>' +
      '<button type="button" class="pl-play" aria-label="Play">' + ICON.play + "</button>" +
      '<button type="button" class="pl-fwd" aria-label="Forward 30 seconds">+30</button>' +
      '<button type="button" class="pl-next" aria-label="Next track">' + ICON.next + "</button>" +
      '<button type="button" class="pl-speed" aria-label="Playback speed">1×</button>' +
      "</div>" +
      '<div class="pl-seek"><span class="pl-cur">0:00</span>' +
      '<input type="range" min="0" max="1000" step="1" value="0" aria-label="Position in track">' +
      '<span class="pl-dur">0:00</span></div>' +
      "</div>";
    document.body.appendChild(bar);
    document.body.classList.add("has-player");
    ["title", "play", "prev", "next", "back", "fwd", "speed", "cur", "dur"].forEach(function (k) {
      ui[k] = bar.querySelector(".pl-" + k);
    });
    ui.range = bar.querySelector("input[type=range]");

    ui.play.addEventListener("click", toggle);
    ui.prev.addEventListener("click", prevTrack);
    ui.next.addEventListener("click", function () { step(1); });
    ui.back.addEventListener("click", function () { skip(-15); });
    ui.fwd.addEventListener("click", function () { skip(30); });
    ui.speed.addEventListener("click", function () {
      var i = SPEEDS.indexOf(state.speed);
      state.speed = SPEEDS[(i + 1) % SPEEDS.length];
      audio.playbackRate = state.speed;
      showSpeed();
      persist();
    });
    ui.range.addEventListener("input", function () {
      seeking = true;
      var d = duration();
      ui.cur.textContent = clock(ui.range.value / 1000 * d);
    });
    ui.range.addEventListener("change", function () {
      var d = duration();
      if (d) audio.currentTime = ui.range.value / 1000 * d;
      seeking = false;
    });
    showSpeed();
  }

  function showSpeed() {
    if (!ui.speed) return;
    ui.speed.textContent = String(state.speed).replace(/^0\./, ".") + "×";
    ui.speed.setAttribute("aria-label", "Playback speed " + state.speed + " times");
  }
  function duration() { return isFinite(audio.duration) && audio.duration > 0 ? audio.duration : (cur >= 0 ? T[cur].d : 0); }
  function skip(s) { if (cur >= 0) audio.currentTime = Math.max(0, Math.min(duration() - 1, audio.currentTime + s)); }

  function savePos() {
    if (cur < 0) return;
    var t = audio.currentTime;
    if (t > 0) { state.pos[T[cur].f] = Math.floor(t); delete state.done[T[cur].f]; }
    state.last = T[cur].f;
    persist();
  }

  // ---------------------------------------------------------------- playing
  function play(i, fromStart) {
    buildBar();
    if (i === cur && !fromStart) { audio.play(); return; }
    if (cur >= 0 && !audio.paused) savePos();
    cur = i;
    var at = fromStart ? 0 : startAt(i);
    audio.src = T[i].u;
    audio.playbackRate = state.speed;
    if (at) {
      audio.addEventListener("loadedmetadata", function once() {
        audio.removeEventListener("loadedmetadata", once);
        audio.currentTime = at;
      });
    }
    ui.title.textContent = T[i].t;
    ui.dur.textContent = clock(T[i].d);
    ui.cur.textContent = clock(at);
    ui.range.value = T[i].d ? Math.round(at / T[i].d * 1000) : 0;
    state.last = T[i].f;
    persist();
    var p = audio.play();
    if (p && p.catch) p.catch(function () { render(); });
    mediaSession();
    render();
  }

  function toggle() {
    if (cur < 0) return;
    if (audio.paused) audio.play(); else audio.pause();
  }
  function step(dir) {
    var k = queue.indexOf(cur) + dir;
    if (k >= 0 && k < queue.length) play(queue[k], true);
  }
  function prevTrack() {
    if (audio.currentTime > 5) audio.currentTime = 0; else step(-1);
  }

  audio.addEventListener("play", render);
  audio.addEventListener("pause", function () { savePos(); render(); });
  audio.addEventListener("ratechange", function () { if (audio.playbackRate !== state.speed) audio.playbackRate = state.speed; });
  audio.addEventListener("timeupdate", function () {
    if (cur < 0) return;
    var d = duration();
    if (!seeking) {
      ui.cur.textContent = clock(audio.currentTime);
      ui.range.value = d ? Math.round(audio.currentTime / d * 1000) : 0;
    }
    if (Date.now() - lastSave > 5000) { lastSave = Date.now(); savePos(); markTracks(); }
    if (navigator.mediaSession && navigator.mediaSession.setPositionState && isFinite(audio.duration)) {
      try { navigator.mediaSession.setPositionState({ duration: audio.duration, playbackRate: audio.playbackRate, position: audio.currentTime }); } catch (e) {}
    }
  });
  audio.addEventListener("ended", function () {
    state.done[T[cur].f] = true;
    delete state.pos[T[cur].f];
    persist();
    var k = queue.indexOf(cur);
    if (k >= 0 && k + 1 < queue.length) play(queue[k + 1], true); else render();
  });
  audio.addEventListener("error", function () {
    if (ui.title && cur >= 0) ui.title.textContent = T[cur].t + " (couldn’t load the audio)";
  });
  window.addEventListener("pagehide", function () { if (cur >= 0) savePos(); });

  function mediaSession() {
    if (!("mediaSession" in navigator) || cur < 0) return;
    try {
      navigator.mediaSession.metadata = new MediaMetadata({
        title: T[cur].t,
        artist: "A. Robert Prouse",
        album: "Ticket to Hell via Dieppe",
        artwork: [{ src: "/images/audiobook.jpg", sizes: "600x600", type: "image/jpeg" }]
      });
      var h = {
        play: function () { audio.play(); },
        pause: function () { audio.pause(); },
        seekbackward: function () { skip(-15); },
        seekforward: function () { skip(30); },
        previoustrack: prevTrack,
        nexttrack: function () { step(1); },
        seekto: function (d) { if (d.seekTime != null) audio.currentTime = d.seekTime; }
      };
      Object.keys(h).forEach(function (k) { try { navigator.mediaSession.setActionHandler(k, h[k]); } catch (e) {} });
    } catch (e) {}
  }

  // ---------------------------------------------------------------- showing state on the page
  function render() {
    if (ui.play) {
      var playing = !audio.paused;
      ui.play.innerHTML = playing ? ICON.pause : ICON.play;
      ui.play.setAttribute("aria-label", playing ? "Pause" : "Play");
      var k = queue.indexOf(cur);
      ui.prev.disabled = cur < 0;
      ui.next.disabled = k < 0 || k + 1 >= queue.length;
    }
    markTracks();
    markButtons();
  }

  function markTracks() {
    document.querySelectorAll("li.track[data-track]").forEach(function (li) {
      var i = +li.getAttribute("data-track"), t = T[i];
      var st = li.querySelector(".t-state"), p = state.pos[t.f] || 0;
      var isCur = i === cur;
      li.classList.toggle("current", isCur);
      li.classList.toggle("playing", isCur && !audio.paused);
      li.classList.toggle("done", !!state.done[t.f] && !isCur);
      var btn = li.querySelector(".t-play");
      btn.setAttribute("aria-label", (isCur && !audio.paused ? "Pause " : "Play ") + t.t);
      if (isCur && !audio.paused) st.textContent = "Playing";
      else if (state.done[t.f]) st.textContent = "Finished";
      else if (p > 0 && p < t.d - 5) st.textContent = mins(t.d - p) + " left";
      else st.textContent = "";
    });
  }

  function markButtons() {
    document.querySelectorAll(".listen-btn").forEach(function (b) {
      var idx = b.getAttribute("data-tracks").split(",").map(Number);
      var label = b.querySelector(".lb-label"), len = b.querySelector(".lb-len");
      if (!b._label) b._label = label.textContent;
      var mine = idx.indexOf(cur) >= 0;
      var icon = b.querySelector("path");
      if (mine && !audio.paused) {
        label.textContent = "Pause"; len.textContent = ""; b.classList.add("playing");
        icon.setAttribute("d", "M7 5h4v14H7zM13 5h4v14h-4z");
        return;
      }
      b.classList.remove("playing");
      icon.setAttribute("d", "M8 5v14l11-7z");
      var left = 0, started = false;
      idx.forEach(function (i) {
        var p = state.pos[T[i].f] || 0;
        if (p > 0 && p < T[i].d - 5) started = true;
        if (!state.done[T[i].f]) left += T[i].d - (p < T[i].d - 5 ? p : 0);
      });
      label.textContent = started || mine ? "Continue listening" : b._label;
      len.textContent = left > 0 ? "· " + mins(left) + (started ? " left" : "") : "· finished";
    });
  }

  // ---------------------------------------------------------------- wiring the page
  // Reading page: the button plays this page's track(s), then stops.
  document.querySelectorAll(".listen-btn").forEach(function (b) {
    b.hidden = false;
    b.addEventListener("click", function () {
      var idx = b.getAttribute("data-tracks").split(",").map(Number);
      if (idx.indexOf(cur) >= 0) { toggle(); return; }
      queue = idx;
      var first = idx[0];
      for (var k = 0; k < idx.length; k++) {               // resume the first unfinished track
        if (!state.done[T[idx[k]].f]) { first = idx[k]; break; }
      }
      if (idx.every(function (i) { return state.done[T[i].f]; })) {
        idx.forEach(function (i) { delete state.done[T[i].f]; });
      }
      play(first);
    });
  });

  // Listen page: every track, played straight through.
  var list = document.querySelectorAll("li.track[data-track]");
  if (list.length) {
    queue = T.map(function (_, i) { return i; });
    list.forEach(function (li) {
      li.querySelector(".t-play").addEventListener("click", function () {
        var i = +li.getAttribute("data-track");
        if (i === cur) toggle(); else play(i);
      });
    });
    var start = document.getElementById("listen-start");
    if (start) start.addEventListener("click", function () { play(0, true); });
    var box = document.getElementById("listen-continue");
    var li = state.last ? indexOfFile(state.last) : -1;
    if (box && li >= 0 && !state.done[T[li].f]) {
      var c = document.createElement("button");
      c.type = "button";
      c.className = "button";
      var at = startAt(li);
      c.textContent = "Continue: " + T[li].t + (at ? " (" + clock(at) + ")" : "");
      c.addEventListener("click", function () { play(li); });
      box.appendChild(c);
      box.hidden = false;
      start.textContent = "Start from the beginning";
      start.className = "button secondary";
    }
  }

  render();
})();
